var builder = WebApplication.CreateBuilder(args);

builder.Services.AddCors(options =>
{
    options.AddPolicy("AdminPolicy", policy =>
    {
        policy
            .WithOrigins("https://admin.example.com")
            .AllowAnyHeader()
            .AllowAnyMethod()
            .AllowCredentials();
    });

    options.AddPolicy("PublicApi", policy =>
    {
        policy
            .WithOrigins(
                "https://app.example.com",
                "https://mobile.example.com")
            .AllowAnyHeader()
            .AllowAnyMethod();
    });
});

builder.Services.AddControllersWithViews();

var app = builder.Build();
app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();

app.UseCors();

app.UseAuthorization();
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

using Microsoft.AspNetCore.Cors;

[EnableCors("PublicApi")]
[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    [HttpGet]
    public IActionResult GetAll()
    {
        return Ok(new[] { "Laptop", "Phone", "Tablet" });
    }
}

using Microsoft.AspNetCore.Cors;

[EnableCors("PublicApi")]
[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    [HttpGet]
    public IActionResult GetRecent()
    {
        return Ok(new[] { "Order 1", "Order 2" });
    }

    [HttpPost]
    [EnableCors("AdminPolicy")]
    public IActionResult Create([FromBody] Order order)
    {
        // Only admin.example.com can POST to this action
        return CreatedAtAction(nameof(GetRecent), order);
    }
}

using Microsoft.AspNetCore.Cors;

[EnableCors("PublicApi")]
[ApiController]
[Route("api/[controller]")]
public class SecretsController : ControllerBase
{
    [HttpGet("public")]
    public IActionResult GetPublic()
    {
        return Ok("This endpoint allows cross-origin requests.");
    }

    [DisableCors]
    [HttpGet("internal")]
    public IActionResult GetInternal()
    {
        // CORS headers are removed from this response
        return Ok("This endpoint does not allow cross-origin requests.");
    }
}
